'use strict';
let ICONS={};
const state={scenario:'cto',engine:'AVC',qty:3,heads:7,index:0,playing:false,tab:'journey'};
const lab={forecast:10,order:3,mode:'ts',match:true,event:'synced',attach:40,heads:7};
let timer=null,returnFocus=null;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const fmt=n=>Number.isInteger(n)?String(n):n.toFixed(1);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function icon(name){const paths=ICONS[name]||ICONS.CircleHelp||[];return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths.map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${esc(v)}"`).join(' ')}></${tag}>`).join('')}</svg>`;}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.outerHTML=icon(el.dataset.icon)});}
function sourceLinks(keys=[]){return keys.length?`<div class="source-links">Official SAP references${keys.map(k=>SOURCES[k]?`<a href="${SOURCES[k].url}" target="_blank" rel="noopener">${SOURCES[k].title} ↗</a>`:'').join('')}</div>`:'';}
function openDialog(title,body,keys=[],eyebrow='EXPLAINED'){
 stop();if(!$('#detail-dialog').open)returnFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body+sourceLinks(keys);$('#dialog-eyebrow').textContent=eyebrow;$('#detail-dialog').showModal();$('#close-dialog').focus();$('#detail-dialog').scrollTop=0;
}
function explain(key){
 if(EXPLANATIONS[key]){const x=EXPLANATIONS[key];openDialog(x.title,x.body,x.sources);return;}
 const r=ROLES.find(r=>r[0]===key);
 if(r){openDialog(r[1],`<p>${r[7]}</p><div class="object-line"><span>INPUTS</span><b>${r[4]}</b></div><div class="object-line"><span>OUTPUTS</span><b>${r[5]}</b></div><div class="object-line"><span>HAND-OFF</span><b>${r[6]}</b></div><p class="callout">${r[3]}.</p>`,key==='ppds'?['pds']:key==='ibp-role'?['ts','obp']:key==='aatp'?['sbc']:key==='configuration'?['vc','avc']:[],'RESPONSIBILITY');return;}
 if(TERMS[key])openDialog(key,`<p>${TERMS[key]}</p>`,[], 'OBJECT & TERM');
}
function stop(){clearTimeout(timer);timer=null;state.playing=false;renderPlay();}
function renderPlay(){if($('#play-label'))$('#play-label').textContent=state.playing?'Pause':'Play process';$('#play')?.setAttribute('aria-pressed',String(state.playing));}
function schedule(){clearTimeout(timer);if(!state.playing)return;timer=setTimeout(()=>{if(state.index<getSteps(state).length-1){state.index++;renderJourney();if(state.index===getSteps(state).length-1)stop();else schedule();}else stop();},Number($('#speed').value));}
function play(){if(state.playing){stop();return;}if(state.index===getSteps(state).length-1)state.index=0;state.playing=true;renderJourney();schedule();}
function setStep(i){stop();state.index=Math.max(0,Math.min(getSteps(state).length-1,i));renderJourney();}
function setScenario(id){stop();state.scenario=id;state.index=0;renderJourney();}
function row(label,value,feature=false){return `<div class="ledger-row${feature?' feature':''}"><span>${label}</span><b>${value}</b></div>`;}
function getJourneyNumbers(s=state){
 const list=SCENARIOS[s.scenario].sequence,passed=id=>list.indexOf(id)>=0&&list.indexOf(id)<=s.index;
 const forecast=passed('forecast')?10:0,order=passed('order')?s.qty:0,synced=passed('sync'),shipped=passed('deliver')?order:0;
 const known=synced?order:0,openForecast=Math.max(0,forecast-known),remaining=known-shipped+openForecast;
 const mts=s.scenario==='mts',mto=s.scenario==='mto',moduleForecast=passed('pir')?(s.heads===7?4:6):0;
 const pir=mts?(passed('pir')?10:0):mto?0:moduleForecast;
 const consumed=mts?(passed('demand')?Math.min(pir,order):0):(passed('release')?Math.min(pir,order):0);
 const openPIR=Math.max(0,pir-consumed);
 const built=mts?(passed('buildPre')?10:0):(passed('build')?s.qty:0);
 return {forecast,order,known,shipped,openForecast,remaining,pir,consumed,openPIR,stock:built-shipped,passed,mts,mto,moduleForecast};
}
function renderLedger(){
 const d=getJourneyNumbers(),p=d.passed,s=state;
 const scope=d.mts?`${s.heads}-head fixed variant · printer units`:'Niagara model aggregate · printer units';
 const ibpStatus=!p('forecast')?'No planning run yet':!p('order')?'Forecast only':!p('sync')?'Order not yet integrated':p('deliver')?'Order + fulfilment feedback processed':'Order integrated & consumption calculated';
 const demScope=d.mts?'Fixed printer variant · strategy 40':d.mto?'Configurable printer parent · strategy 25':`${s.heads}-head module · illustrative strategy 70`;
 let demandRows=d.mts?row('Initial PIR reference',d.pir)+row('Open customer demand',d.order-d.shipped)+row('Residual PIR',d.openPIR,true):d.mto?row('Parent PIR',0)+row('Open customer demand',d.order-d.shipped,true):row('Initial module PIR',d.pir)+row('Eligible consumed / reduced',d.consumed)+row('Residual module PIR',d.openPIR,true);
 let demandFoot=d.mts?'Residual PIR + open order is demand still to fulfil. Stock is shown separately.':d.mto?'This route has no final-printer PIR. Components could be preplanned in a separate design.':`Parent printer demand: ${d.order-d.shipped}. Module consumption is shown at production release; component issue reduces physical stock later.`;
 $('#ledger').innerHTML=`<div class="ledger-box"><h4>SAP IBP <button class="help-icon" data-explain="ibp" aria-label="Explain IBP demand">?</button></h4><span class="ledger-scope">${scope}<br>Illustrative period-accounting view</span>${row('Baseline forecast',d.forecast)}${row('Known order / fulfilled',d.known)}${row('Open forecast',d.openForecast,true)}<div class="ledger-foot">${ibpStatus}. ${p('sync')?`Outstanding order ${d.known-d.shipped} + open forecast ${d.openForecast} = ${d.remaining} remaining demand.`:''}</div></div><div class="ledger-box"><h4>S/4HANA demand <button class="help-icon" data-explain="consumption" aria-label="Explain S/4 demand">?</button></h4><span class="ledger-scope">${demScope}</span>${demandRows}<div class="ledger-foot">${demandFoot}</div></div><div class="ledger-box"><h4>Physical fulfilment</h4><span class="ledger-scope">Finished printer units · ${d.mts?'anonymous stock':'order SO-1042 stock E'}</span>${row('Finished printers in stock',d.stock)}${row('Shipped on SO-1042',d.shipped)}<div class="ledger-foot"><span class="state-pill">${p('invoice')?'Invoiced':p('deliver')?'Delivered':p('build')||p('buildPre')&&d.mts?'Ready stock':p('release')?'In production':p('promise')?'Promise agreed':p('order')?'Order received':p('buildPre')?'Modules ready':'Preparing supply'}</span></div></div>`;
}
function renderJourney(){
 const steps=getSteps(state);state.index=Math.min(state.index,steps.length-1);const step=steps[state.index];
 $$('[data-scenario]').forEach(b=>{b.classList.toggle('active',b.dataset.scenario===state.scenario);b.setAttribute('aria-pressed',String(b.dataset.scenario===state.scenario));});
 $$('[data-engine]').forEach(b=>{b.classList.toggle('active',b.dataset.engine===state.engine);b.setAttribute('aria-pressed',String(b.dataset.engine===state.engine));});
 $('#scenario-note').textContent=SCENARIOS[state.scenario].note;
 renderProcessDiagram();
 $('#route-count').textContent=`${steps.length} steps · ${DIAGRAM_LANES.length} lanes`;
 $('#now-playing').innerHTML=`<b>${esc(step.title)}</b><small>${esc(step.owner)}</small>`;
 $('#step-card').innerHTML=`<div><span class="step-owner">${icon(step.icon)}${step.owner}</span><h3>${step.title}</h3><p>${step.summary}</p></div><div class="current-actions"><button class="button secondary" id="open-step">${icon('BookOpen')} Read the step</button></div>`;
 const d=getJourneyNumbers();
 $('#order-card').innerHTML=`<header><b>${d.order?'SO-1042 / 10 · '+state.qty+' printers':'The printer in this example'}</b><span>${state.engine} · ${SCENARIOS[state.scenario].title}</span></header><div class="printer-parts"><div class="part">${icon('Package')}Feeder<small>1 per printer</small></div><span class="map-link">→</span><div class="part print">${icon('Printer')}${state.heads}-head print module<small>${state.heads} individual heads / module</small></div><span class="map-link">→</span><div class="part">${icon('Layers3')}Finishing<small>1 per printer</small></div></div><p>${d.order?`Order content: ${state.qty} feeders + ${state.qty} print modules + ${state.qty} finishing modules. The print modules contain ${state.qty*state.heads} individual heads in total.`:'A modular product: forecast mix and valid configuration are separate concepts.'}</p>`;
 $('#step-count').textContent=`${state.index+1} / ${steps.length}`;$('#progress-fill').style.width=`${(state.index+1)/steps.length*100}%`;
 $('#back').disabled=state.index===0;$('#next').disabled=state.index===steps.length-1;
 renderLedger();renderPlay();
 focusActiveNode();
}
function consumptionResult(f,o,match){const consumed=match?Math.min(f,o):0;return{consumed,open:f-consumed,total:o+f-consumed};}
function getLabNumbers(l=lab){const actual=l.event==='before'||l.event==='cancelled'?0:l.order;const integrated=l.mode!=='none'&&(l.event==='synced'||l.event==='cancelled');const known=integrated?actual:0;return{actual,integrated,known,...consumptionResult(l.forecast,known,l.match),s4:consumptionResult(l.forecast,actual,l.match)};}
function renderLab(){
 $('#forecast-output').textContent=lab.forecast;$('#order-output').textContent=lab.order;$('#attach-output').textContent=lab.attach+'%';
 $$('[data-event]').forEach(b=>{b.classList.toggle('active',b.dataset.event===lab.event);b.setAttribute('aria-pressed',String(b.dataset.event===lab.event));});
 const d=getLabNumbers(),label={before:'Before a customer order exists',arrived:'S/4 has the order. IBP is still waiting.',synced:lab.mode==='none'?'The forecast-only view still has no order input.':'The order is known and consumption has run.',cancelled:'Cancellation releases the expected demand again.'}[lab.event];
 const modeLabel={ts:'Time-series consumption · illustrative key figures',obp:'Order-based planning · illustrative matched demand',none:'Forecast-only design · no order-consumption output'}[lab.mode];
 let message=lab.event==='before'?`There are ${lab.forecast} expected units and no known customer demand. Nothing has been consumed.`:lab.event==='arrived'?`The ${lab.order}-printer order is already in S/4. IBP’s displayed order quantity is still 0 until integration and calculation. This timing gap is normal in a staged interface.`:lab.event==='cancelled'?`The order is cancelled before delivery. After updates and recalculation, ${lab.forecast} units are expected again. Review existing supply: firm production or purchase orders do not automatically vanish.`:lab.mode==='none'?'IBP still displays the forecast. There is no configured order input or consumption output in this example. The sales order is real in S/4; an IBP total of “forecast + order” cannot be inferred.':!lab.match?`The order cannot consume this forecast bucket. ${lab.order} + ${lab.forecast} = ${lab.order+lab.forecast} across the unmatched demand shown. Review timing and matching; do not force a same-period net just because the monthly totals look related.`:lab.order>lab.forecast?`The order exceeds the forecast by ${lab.order-lab.forecast}. All ${lab.forecast} forecast units are consumed; total demand grows to ${lab.order}.`: `The order replaces ${d.consumed} anticipated units. The baseline remains ${lab.forecast}; ${d.open} are still expected from future orders. Total demand is ${d.total}, not ${lab.forecast+lab.order}.`;
 const available=lab.mode!=='none';const denom=Math.max(1,d.total);
 $('#lab-result').innerHTML=`<article class="lab-result-card"><p class="eyebrow">${modeLabel}</p><h3>${label}</h3>${renderDemandDiagram(d)}<div class="big-equation"><div class="equation-item"><strong>${d.known}</strong><span>Known order in IBP</span></div><span class="equation-sign">+</span><div class="equation-item"><strong>${available?d.open:lab.forecast}</strong><span>${available?'Open forecast':'Forecast only'}</span></div><span class="equation-sign">=</span><div class="equation-item focus"><strong>${available?d.total:'—'}</strong><span>${available?'Total demand':'Not calculated'}</span></div></div><div class="demand-bar" aria-label="${d.known} known units and ${d.open} unconsumed forecast units"><span class="known" style="width:${d.known/denom*100}%"></span><span class="forecast" style="width:${d.open/denom*100}%"></span></div><div class="bar-legend"><span>Known order</span><span>${available?'Open forecast':'Forecast'}</span><b>Baseline forecast: ${lab.forecast}</b></div><p class="callout ${!lab.match||lab.mode==='none'?'warn':''}">${message}</p><div class="system-pair"><div><h4>S/4HANA in this numeric example</h4><p>Fixed printer variant, strategy 40: initial PIR ${lab.forecast}, customer requirement ${d.actual}, residual PIR ${d.s4.open}.</p><p>Operational demand shown: ${d.s4.total}. This is demand, not net procurement or available stock.</p></div><div><h4>What makes this work?</h4><p>${lab.mode==='ts'?'Integrate the sales-order input, run the consumption calculation, and feed its intended result to supply planning.':lab.mode==='obp'?'Integrate orders, assign the relevant consumption profile and run planning with the required demand selections.':'Design the order/actuals interface and the demand calculation before treating this as an order-aware IBP view.'}</p><button class="text-link" data-explain="ibp">What about delivery and goods issue? ${icon('ArrowUpRight')}</button></div></div></article>`;
 const f7=lab.forecast*lab.attach/100,f5=lab.forecast-f7;
 const vals=[{heads:5,forecast:f5},{heads:7,forecast:f7}].map(x=>({...x,need:x.heads===lab.heads?d.actual:0})).map(x=>({...x,...consumptionResult(x.forecast,x.need,true)}));
 const selected=vals.find(x=>x.heads===lab.heads),gap=Math.max(0,selected.need-selected.forecast);
 $('#module-result').innerHTML=`<table class="module-table"><thead><tr><th>MODULE</th><th>FORECAST</th><th>ORDER NEED</th><th>RESIDUAL PLAN</th><th>NEED ABOVE PLAN</th></tr></thead><tbody>${vals.map(x=>`<tr class="${x.heads===lab.heads?'highlight':''}"><td>${x.heads}-head module</td><td>${fmt(x.forecast)}</td><td>${x.need}</td><td>${fmt(x.open)}</td><td class="${x.need>x.forecast?'alert':''}">${fmt(Math.max(0,x.need-x.forecast))}</td></tr>`).join('')}</tbody></table><p class="callout${gap?' warn':''}">${gap?`${d.actual} ordered ${lab.heads}-head modules exceed their plan of ${fmt(selected.forecast)} by ${fmt(gap)}. ${d.actual<=lab.forecast?'The printer-level total is still within the forecast. ':''}Review this specific module’s supply and capacity.`:`The selected module need is within its illustrative plan. That is plan coverage; it does not prove stock availability or a feasible assembly date.`}</p><p class="small muted">Separate module example: eligible module consumption is assumed after the relevant production requirements exist. The printer-level date-match setting above is not applied to this independent module example. Forecast by module and consumption at model level are alternative views to reconcile, not quantities to add.</p>`;
}
function syncLabControls(){[['lab-forecast','forecast'],['lab-order','order'],['ibp-mode','mode'],['attach','attach'],['lab-heads','heads']].forEach(([id,k])=>$('#'+id).value=lab[k]);$('#match').value=lab.match?'yes':'no';renderLab();}
function renderCompare(){
 const scenarios=Object.entries(SCENARIOS);const rows=[['Production trigger','trigger'],['Stock before order','stock'],['Active PIR level','pir'],['Before the order','before'],['After the order','after'],['Inventory segment','segment'],['Main exposure','risk']];
 $('#comparison').innerHTML=`<div class="compare-table-wrap"><table class="compare-table"><thead><tr><th>FULFILMENT DESIGN</th>${scenarios.map(([k,s])=>`<th>${s.title}<small>${k==='mts'?'Fixed stocked execution':k==='mto'?'Customer-specific production':'Customer selection over prepared modules'}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([title,k])=>`<tr><td>${title}</td>${scenarios.map(([,s])=>`<td>${s[k]}</td>`).join('')}</tr>`).join('')}<tr><td>Follow the same order</td>${scenarios.map(([k])=>`<td><button class="text-link" data-explore="${k}">Open this journey ${icon('ArrowRight')}</button></td>`).join('')}</tr></tbody></table></div>`;
 $('#compare-response').innerHTML=`<div class="response-line"><b>MTS</b><span>3 sales units consume 3 of 10 printer PIR units. Use 3 of the 10 already-built matching printers; 7 remain after shipment.</span></div><div class="response-line"><b>MTO</b><span>3 order-specific printers trigger supply. No parent PIR exists here. Procure and manufacture the selected content before delivery.</span></div><div class="response-line"><b>CTO</b><span>3 printers require 3 of the 4 planned 7-head modules. Eligible module consumption leaves 1 in the residual plan. Final assembly still happens for the order.</span></div><p class="small muted">These examples differ in planning level and stock point. Equal forecast numbers do not make their stock risks equal.</p>`;
 $('#strategies').innerHTML=`<div class="strategy-cards">${[['40','Fixed-variant MTS','Forecast the finished printer'],['25','Configured MTO','Order drives the parent'],['70','Assembly planning','Forecast common modules'],['56 / 89 / 82','Alternative designs','Characteristic planning / assembly processing']].map(x=>`<button data-explain="strategies"><strong>${x[0]}</strong><b>${x[1]}</b><small>${x[2]} ↗</small></button>`).join('')}</div>`;
}
function renderReference(filter=''){
 const f=filter.trim().toLowerCase();let roles=ROLES.filter(r=>r.join(' ').toLowerCase().includes(f)),terms=Object.entries(TERMS).filter(([k,v])=>(k+' '+v).toLowerCase().includes(f));
 $('#foundation-map').innerHTML=`${[['engineering','Engineering','eBOM → manufacturing structure'],['configuration','VC / AVC model','Valid combinations & selection'],['ppds','Manufacturing source','Production version → PDS'],['mrp-role','Operational planning','Materials + resources + execution']].map(([k,t,d],i)=>`${i?'<span>→</span>':''}<button data-explain="${k}"><b>${t}</b><small>${d}</small></button>`).join('')}`;
 $('#responsibilities').innerHTML=roles.length?roles.map(r=>`<button class="role-card" data-explain="${r[0]}"><header>${icon(r[2])}<span>${String(ROLES.indexOf(r)+1).padStart(2,'0')} / 10</span></header><h3>${r[1]}</h3><p>${r[3]}.</p><footer>Inputs, outputs & hand-offs ↗</footer></button>`).join(''):'<p class="empty">No responsibilities match. Try “PIR”, “stock” or “configuration”.</p>';
 $('#glossary').innerHTML=terms.length?terms.map(([k])=>`<button data-explain="${esc(k)}">${k} +</button>`).join(''):'<p class="muted small">No glossary terms match this search.</p>';
 $('#sources').innerHTML=Object.values(SOURCES).map(x=>`<a href="${x.url}" target="_blank" rel="noopener">${x.title} ↗</a>`).join('');
}
function setTab(tab,scroll=false){if(!['journey','demand','compare','reference'].includes(tab))tab='journey';stop();state.tab=tab;$$('.view').forEach(v=>v.hidden=v.id!==tab);$$('[data-tab]').forEach(a=>{a.classList.toggle('active',a.dataset.tab===tab);if(a.dataset.tab===tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const titles={journey:['INTERACTIVE PROCESS MAP','Order process by application'],demand:['DEMAND CALCULATION','Forecast consumption and order demand'],compare:['FULFILMENT AND CONFIGURATION','MTS, MTO and CTO comparison'],reference:['MASTER DATA AND APPLICATIONS','Application responsibilities and planning objects']};$('#section-kicker').textContent=titles[tab][0];$('#section-title').textContent=titles[tab][1];if(tab==='demand')renderLab();if(scroll)$('.workspace-heading').scrollIntoView({behavior:'smooth',block:'start'});}
function routeFromHash(scroll=false){setTab(location.hash.slice(1)||'journey',scroll);}
async function init(){
 try{ICONS=await(await fetch('assets/icons.json')).json();}catch{ICONS={};}
 hydrate();renderJourney();renderCompare();renderReference();renderLab();routeFromHash();
 document.addEventListener('click',e=>{const b=e.target.closest('[data-explain]');if(b){explain(b.dataset.explain);return;}const node=e.target.closest('[data-node]');if(node){setStep(Number(node.dataset.step));document.querySelector(`[data-node="${node.dataset.node}"]`)?.focus({preventScroll:true});showStepDetails(node.dataset.node);return;}const st=e.target.closest('[data-step]');if(st){setStep(Number(st.dataset.step));return;}if(e.target.closest('#open-step, #step-details')){showStepDetails();return;}const sc=e.target.closest('[data-scenario]');if(sc){setScenario(sc.dataset.scenario);return;}const en=e.target.closest('[data-engine]');if(en){stop();state.engine=en.dataset.engine;renderJourney();return;}const evt=e.target.closest('[data-event]');if(evt){lab.event=evt.dataset.event;renderLab();return;}const preset=e.target.closest('[data-preset]');if(preset){Object.assign(lab,{forecast:10,order:3,match:true,event:'synced',attach:40,heads:7,mode:'ts'});if(preset.dataset.preset==='excess')lab.order=14;if(preset.dataset.preset==='outside')lab.match=false;if(preset.dataset.preset==='mix')lab.order=7;syncLabControls();return;}const explore=e.target.closest('[data-explore]');if(explore){setScenario(explore.dataset.explore);location.hash='journey';setTab('journey',true);return;}const a=e.target.closest('a[href^="#"]');if(a&&['journey','demand','compare','reference'].includes(a.hash.slice(1))){e.preventDefault();history.pushState(null,'',a.hash);setTab(a.hash.slice(1),true);}});
 $('#play').onclick=play;$('#next').onclick=()=>{setStep(state.index+1);focusActiveNode(true);};$('#back').onclick=()=>{setStep(state.index-1);focusActiveNode(true);};$('#reset').onclick=()=>setStep(0);$('#speed').onchange=()=>{if(state.playing)schedule();};
 $('#quantity').onchange=e=>{stop();state.qty=Number(e.target.value);renderJourney();};$('#heads').onchange=e=>{stop();state.heads=Number(e.target.value);renderJourney();};
 $('#expand-map').onclick=async()=>{if(document.fullscreenElement)await document.exitFullscreen();else await $('#process-board').requestFullscreen();};
 $('#zoom-in').onclick=()=>changeDiagramZoom(.15);$('#zoom-out').onclick=()=>changeDiagramZoom(-.15);$('#zoom-fit').onclick=()=>{diagramZoom=null;sizeDiagram();};
 new ResizeObserver(()=>sizeDiagram()).observe($('#diagram-viewport'));
 new ResizeObserver(()=>document.documentElement.style.setProperty('--topbar-height',$('.topbar').getBoundingClientRect().height+'px')).observe($('.topbar'));

 $('#close-dialog').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').addEventListener('close',()=>returnFocus?.isConnected&&returnFocus.focus());$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
 $('#lab-forecast').oninput=e=>{lab.forecast=Number(e.target.value);renderLab();};$('#lab-order').oninput=e=>{lab.order=Number(e.target.value);renderLab();};$('#ibp-mode').onchange=e=>{lab.mode=e.target.value;renderLab();};$('#match').onchange=e=>{lab.match=e.target.value==='yes';renderLab();};$('#attach').oninput=e=>{lab.attach=Number(e.target.value);renderLab();};$('#lab-heads').onchange=e=>{lab.heads=Number(e.target.value);renderLab();};$('#reference-search').oninput=e=>renderReference(e.target.value);
 window.addEventListener('hashchange',()=>routeFromHash(true));window.addEventListener('popstate',()=>routeFromHash(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
 document.addEventListener('keydown',e=>{if($('#detail-dialog').open||/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)||state.tab!=='journey')return;if(e.key==='ArrowRight'){e.preventDefault();setStep(state.index+1);}if(e.key==='ArrowLeft'){e.preventDefault();setStep(state.index-1);}});
 document.documentElement.dataset.ready='true';
}
init();
